import{z as c,x as E,o as t,c as m,q as n,j as l,D as i,d as a,s,S as d,b as o}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"内核命令行","description":"","frontmatter":{"title":"内核命令行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-cmdline.md","filePath":"cs/kernel-cmdline.md","lastUpdated":1791063341000}'),p={name:"cs/kernel-cmdline.md"};function A(B,e,u,h,C,f){const r=E("Mermaid");return t(),m("div",null,[e[2]||(e[2]=n('<h1 id="内核命令行" tabindex="-1">内核命令行 <a class="header-anchor" href="#内核命令行" aria-label="Permalink to &quot;内核命令行&quot;">​</a></h1><div class="epigraph"><p>启动加载器把字符串交给内核：根设备、console、[KPTI](/cs/kpti-os) 开关、init=，解析发生在 PID 1 之前。</p><footer>—— 据 Linux kernel-parameters 文档；[initramfs](/cs/initramfs-pivot) 为根设备先修</footer></div><p><a href="/cs/systemd-units">systemd</a> 读自己的配置。更早： <strong>cmdline</strong> 已决定根、调试、隔离。缺口是参数如何进 <code>initramfs</code> 与内核子系统。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>root=</code>、<code>ro</code>、<code>quiet</code>、<code>isolcpus</code>、<code>mem=</code>。未知参数可留给用户态。缺口：安全——恶意 cmdline 改 <code>init=</code>；度量启动要把 cmdline 进 PCR。本课不把全部参数当词典。</p><p><span class="marginnote">模块参数可 <code>modprobe.blacklist</code>。与 sysctl 的分工：cmdline 更早、一次性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>bootloader 填 <code>boot_params</code> → 内核 parse → 子系统注册回调。对照 <a href="/cs/cpufreq-governor">cpufreq</a>：可 <code>intel_pstate=disable</code>。对照 <a href="/cs/netns-veth">netns</a>：太早无 ns。对照 Secure Boot：签名不含 cmdline 内容，故 PCR 要量它。</p>',8)),(t(),l(d,null,{default:i(()=>[s(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BL%5B%22bootloader%22%5D%20--%3E%20S%5B%22cmdline%20%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%0A%20%20S%20--%3E%20PAR%5B%22%E5%86%85%E6%A0%B8%E8%A7%A3%E6%9E%90%22%5D%0A%20%20PAR%20--%3E%20SUB%5B%22%E5%AD%90%E7%B3%BB%E7%BB%9F%E4%B8%8E%20initramfs%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,[a("cmdline 是内核的早期配置 ABI，把硬件与调试开关从编译里解放。它也是攻击面。不要写成 grub 美化。与 "),o("a",{href:"/cs/sched-ext"},"sched_ext"),a("：可后期加载，不必 cmdline。")],-1)),e[5]||(e[5]=o("p",null,"发行版在 grub 里拼这串，与用户文档必须一致。",-1)),(t(),l(d,null,{default:i(()=>[s(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20AT%5B%22%E6%94%B9%20grub%20%E6%9D%A1%E7%9B%AE%E5%8A%A0%20init%3D%2Fbin%2Fsh%22%5D%20--%3E%20SB%7B%22Secure%20Boot%20%E9%AA%8C%E7%AD%BE%E5%90%8D%22%7D%0A%20%20SB%20--%3E%7C%22%E5%8F%AA%E9%AA%8C%E5%86%85%E6%A0%B8%E9%95%9C%E5%83%8F%EF%BC%8Ccmdline%20%E4%B8%8D%E5%9C%A8%E5%86%85%22%7C%20PASS%5B%22%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%EF%BC%8C%E6%81%B6%E6%84%8F%E5%8F%82%E6%95%B0%E7%94%9F%E6%95%88%22%5D%0A%20%20SB%20--%3E%7C%22%E5%90%8C%E4%B8%80%E6%97%B6%E5%88%BB%22%7C%20PCR%5B%22TPM%20%E6%8A%8A%20cmdline%20%E5%93%88%E5%B8%8C%E6%89%A9%E5%B1%95%E8%BF%9B%20PCR%22%5D%0A%20%20PCR%20--%3E%20ATT%5B%22%E8%BF%9C%E7%A8%8B%E8%AF%81%E6%98%8E%E6%97%B6%E5%93%88%E5%B8%8C%E5%AF%B9%E4%B8%8D%E4%B8%8A%E6%A0%87%E5%87%86%E5%80%BC%22%5D%0A%20%20PASS%20--%3E%20DET%5B%22%E8%A2%AB%E5%BA%A6%E9%87%8F%E5%90%AF%E5%8A%A8%E5%8F%91%E7%8E%B0%22%5D%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<p><span class="marginnote">常见误区：开了 Secure Boot 就以为 cmdline 也被保护了。签名只盖住内核镜像文件；这串参数以明文存在 grub 配置里，谁改了 grub 条目谁就能塞进 <code>init=</code>。度量启动（把它哈希进 PCR）才是发现篡改的手段。</span></p><p><span class="marginnote">数字实例：一条典型 cmdline 长这样——<code>root=/dev/nvme0n1p2 ro quiet mem=4G</code>：根分区在第一块 NVMe 盘第 2 分区、只读挂载再由 init 重挂、少打印内核日志、只认 4 GB 内存。<code>mem=4G</code> 在 8 GB 机器上会让内核直接「假装」另一半不存在。</span></p><p><span class="marginnote">术语翻译：PCR 可以想象成 TPM 芯片里一组「只进不出」的印章台——新值只能是「旧印章混合新内容」的哈希，读得出但改写不了历史；启动链上每一环（固件、内核、cmdline）依次盖一章，事后比对印章就能还原这台机器是怎么启动的。</span></p><p>实现上：init= 能换成任意用户态，度量必须覆盖这串。未知参数留给用户态，initramfs 脚本会读。isolcpus 与 nohz_full 常一起出现在 RT 机器。 读法上只引用<a href="/cs/systemd-units">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>内核命令行</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 arch 特定。不保证 kexec 二次启动的参数策略。下一课描述硬件：设备树与 ACPI。</p><p>版本字段会变，课序钉的是机制对象「内核命令行」，不是某一主线内核的结构体名。 后课默认：早期行为可由 cmdline 固定。如何枚举设备，下一课 DT/ACPI。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cmdline 在 PID 1 前配置内核与根。</li><li>应纳入度量；内容本身通常不在内核签名里。</li><li>设备树与 ACPI 是下一课。</li><li>出处：kernel-parameters.txt；boot protocol。</li></ul>',11))])}const D=c(p,[["render",A]]);export{b as __pageData,D as default};
